  const [clientEnEditionAgenda, setClientEnEditionAgenda] = useState(null);
  // Onglets du panneau « Tâches en attente » : PRÊTES à planifier
  // (glissables maintenant) vs EN ATTENTE (bloquées par un dépôt non
